    (120, 100, 1002, '角色管理', 'MENU', 'SystemRole', '/system/roles', 'system/role/index', 'Avatar', 20, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 0),
