    component_path = VALUES(component_path),
    sort_no = VALUES(sort_no),
    updated_time = CURRENT_TIMESTAMP(3);

INSERT INTO sys_role_permission (
    role_id, permission_id, created_time, updated_time, deleted
)
SELECT 1, p.id, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 0
FROM sys_permission p
WHERE p.id BETWEEN 1001 AND 1006
ON DUPLICATE KEY UPDATE
    deleted = 0,
    updated_time = CURRENT_TIMESTAMP(3);

INSERT INTO sys_role_menu (
    role_id, menu_id, created_time, updated_time, deleted
)
SELECT 1, m.id, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 0
FROM sys_menu m
WHERE m.id IN (100, 110, 120, 130, 140, 150, 160)
ON DUPLICATE KEY UPDATE
    deleted = 0,
    updated_time = CURRENT_TIMESTAMP(3);
